      const parsed = parseNutritionText(extractedText);

      setRegisterData((prev) => ({
        ...prev,
        nutritionFileName: file.name,
        nutritionText: extractedText,
        allowedFoods: parsed.allowed,
        forbiddenFoods: parsed.forbidden,
      }));

      setPdfMessage("הקובץ נקרא בהצלחה.");
    } catch (error) {
      console.error(error);
      setPdfMessage("לא הצלחתי לקרוא את ה־PDF. נסה PDF עם טקסט ברור או הדבק טקסט ידנית.");
